// Local decorative ingredient illustrations; not photographs of retailer products.
const pictures=[[/onion|shallot/i,'onion'],[/chill|chili|capsicum|bell pepper/i,'chilli'],[/lemon|lime/i,'lemon'],[/garlic/i,'garlic'],[/tomato/i,'tomato'],[/carrot/i,'carrot'],[/peas/i,'peas'],[/broccoli|cauliflower/i,'broccoli'],[/spinach|lettuce|cabbage|parsley|coriander|mint|leaf|leaves|herb/i,'leaf'],[/rice|quinoa|bulgur|freekeh|wheat|oats|flour/i,'rice'],[/bread|pita|roti|wrap|tortilla|khameer|regag/i,'bread'],[/shrimp|prawn|shellfish/i,'shrimp'],[/fish|tuna|salmon|mackerel|bream/i,'fish'],[/egg/i,'egg'],[/yogurt|milk|cream|labneh|jameed|qishta/i,'milk'],[/cheese|paneer/i,'cheese'],[/chicken|poultry/i,'chicken'],[/beef|lamb|goat|camel|meat|liver|sausage/i,'meat'],[/potato/i,'potato'],[/cucumber|courgette/i,'cucumber'],[/chickpea|lentil|bean|dal|fava|pulse/i,'beans'],[/coconut/i,'coconut'],[/mushroom/i,'mushroom'],[/oil|olive/i,'oil'],[/salt|spice|cumin|pepper|cinnamon|turmeric|cardamom|bzar|paprika|sumac/i,'spice']];
export function ingredientPicture(name){return '/ingredients/'+(pictures.find(([pattern])=>pattern.test(String(name)))?.[1]||'basket')+'.png';}
